import static org.mockito.Mockito.when;
import static org.mockito.internal.matchers.ArgumentMatchers.any;

public class InvocationMatcher_captureArgumentsFrom_TriageGen1Test {

    // Interface to simulate CapturesArguments behavior
    public interface CapturesArguments {
        void captureFrom(Object argument);
    }

    // Helper to create a Method object
    private Method getMethod(String name, boolean isVarArgs) throws NoSuchMethodException {
        // Using Object.toString() as a base to find a method
        Method m = Object.class.getMethod(name, Object.class);
        // Note: In real reflection, you can't easily change isVarArgs on an existing method object.
        // However, for the sake of the unit test logic, we will mock the Method object.
        return m;
    }

    @Test
    public void testCaptureArgumentsFrom_WithVarArgs_ThrowsException() throws NoSuchMethodException {
        Invocation invocation = mock(Invocation.class);
        Method varArgsMethod = mock(Method.class);

        when(varArgsMethod.isVarArgs()).thenReturn(true);
        when(invocation.getMethod()).thenReturn(varArgsMethod);
        when(invocation.getRawArguments()).thenReturn(new Object[]{1, "two", new Object[]{3, 4}});

        InvocationMatcher matcher = new InvocationMatcher(invocation);
        // We need to access the private field 'matchers' or use a constructor that populates it.
        // Since the provided snippet implies matchers is a field in InvocationMatcher:
        // We assume the constructor or a way to set matchers exists.

        // Because 'matchers' is not explicitly provided in the constructor in the prompt's signature 
        // but used in the code, we assume it's initialized via the constructor provided.
        // For this test, we use the constructor: public InvocationMatcher(Invocation invocation, List<Matcher> matchers);

        InvocationMatcher matcherWithList = new InvocationMatcher(invocation, new ArrayList<>());

        assertThrows(UnsupportedOperationException.class, () -> {
            matcherWithList.captureArgumentsFrom(invocation);
        });
    }

    @Test
    public void testCaptureArgumentsFrom_WithoutVarArgs_CapturesCorrectArguments() throws NoSuchMethodException {
        Invocation invocation = mock(Invocation.class);
        Method normalMethod = mock(Method.class);

        when(normalMethod.isVarArgs()).thenReturn(false);
        when(invocation.getMethod()).thenReturn(normalMethod);

        Object arg1 = "first";
        Object arg2 = "second";
        when(invocation.getRawArguments()).thenReturn(new Object[]{arg1, arg2});
        when(invocation.getArgumentAt(0, Object.class)).thenReturn(arg1);
        when(invocation.getArgumentAt(1, Object.class)).thenReturn(arg2);

        CapturesArguments capturer1 = mock(CapturesArguments.class);
        CapturesArguments capturer2 = mock(CapturesArguments.class);
        Matcher nonCapturer = mock(Matcher.class);

        List<Matcher> matchers = Arrays.asList(capturer1, nonCapturer, capturer2);
        InvocationMatcher matcher = new InvocationMatcher(invocation, matchers);

        matcher.captureArgumentsFrom(invocation);

        verify(capturer1).captureFrom(arg1);
        verify(capturer2).captureFrom(arg2);
        // nonCapturer should not be called because it's not an instance of CapturesArguments
    }

    @Test
    public void testCaptureArgumentsFrom_WithoutVarArgs_NoMatchers() throws NoSuchMethodException {
        Invocation invocation = mock(Invocation.class);
        Method normalMethod = mock(Method.class);

        when(normalMethod.isVarArgs()).thenReturn(false);
        when(invocation.getMethod()).thenReturn(normalMethod);
        when(invocation.getRawArguments()).thenReturn(new Object[]{});

        InvocationMatcher matcher = new InvocationMatcher(invocation, new ArrayList<>());

        // Should not throw exception and should do nothing
        matcher.captureArgumentsFrom(invocation);
    }

    @Test
    public void testCaptureArgumentsFrom_WithoutVarArgs_MatchersExistButNoneAreCapturers() throws NoSuchMethodException {
        Invocation invocation = mock(Invocation.class);
        Method normalMethod = mock(Method.class);

        when(normalMethod.isVarArgs()).thenReturn(false);
        when(invocation.getMethod()).thenReturn(normalMethod);
        when(invocation.getRawArguments()).thenReturn(new Object[]{"data"});
        when(invocation.getArgumentAt(0, Object.class)).thenReturn("data");

        Matcher regularMatcher = mock(Matcher.class);
        List<Matcher> matchers = Arrays.asList(regularMatcher);
        InvocationMatcher matcher = new InvocationMatcher(invocation, matchers);

        matcher.captureArgumentsFrom(invocation);

        // Verify no interaction with the mock as it's not a CapturesArguments
        verify(regularMatcher, org.mockito.Mockito.never()).captureFrom(any());
    }
}
